# Plan: simplify exact ground-footprint cell runs, not an invented schematic footprint.
def path_cells(cells):
 rows=collections.defaultdict(list)
 for x,z in cells:rows[z].append(x)
 parts=[]
 for z,xs in rows.items():
  xs=sorted(set(xs));a=prev=xs[0]
  for x in xs[1:]+[None]:
   if x==prev+1:prev=x;continue
   parts.append(f'M{a},{z}h{prev-a+1}v1H{a}z')
   if x is not None:a=prev=x
 return ''.join(parts)
